// Types for the water dashboard platform's lake data files.
//
// Data files are committed snapshots generated by the utahwater pipeline
// (USGS API → JSON). The model works in US customary units: elevation in
// feet, surface area in acres, volume in acre-ft (1 acre-ft over 1 acre
// raises the level 1 ft).

/** Provenance block embedded in every data file's `meta` key. */
export interface DataMeta {
  title?: string;
  units?: string;
  water_year?: string;
  generated_utc?: string;
  api?: string;
  data_as_of?: string | Record<string, string>;
  record?: string;
  site?: string;
  sites?: Record<string, string>;
  method?: string;
  sources?: string | Record<string, string>;
  [key: string]: unknown;
}

/** One observed water year (Oct 1 – Sep 30) of lake level. */
export interface LevelRow {
  year: number;
  start_ft: number | null;
  end_ft: number | null;
  partial: boolean;
  missing_days: number;
}

export interface LevelsData {
  meta: DataMeta;
  data: LevelRow[];
}

/**
 * One water year of source inflow. Per-gauge values are flat keys:
 * `<source>` (acre-ft), `<source>_days` (days on record),
 * `<source>_missing` (days missing).
 */
export interface InflowRow {
  year: number;
  partial: boolean;
  complete: boolean;
  total: number | null;
  [key: string]: number | boolean | null;
}

export interface InflowsData {
  meta: DataMeta;
  data: InflowRow[];
}

/** One point of the elevation → surface-area (hypsometric) curve. */
export interface ElevAreaPoint {
  elev_ft: number;
  area_acres: number;
}

/** Per-year calibrated evaporation depth (mass-balance residual). */
export interface CalibrationYear {
  year: number;
  e: number;
  inflow_acft: number;
  area_avg_ac: number;
  h_start: number;
  h_end: number;
  bear_missing: boolean;
}

export interface CalibrationData {
  meta: DataMeta;
  /** Mean e over complete years; the fallback when a year has no calibrated value. */
  e_ft_per_yr: number;
  e_stats: {
    n_complete: number;
    n_bear_missing: number;
    e_mean: number;
    e_median: number;
    e_stdev: number;
    e_min: number;
    e_max: number;
  };
  e_per_year: CalibrationYear[];
  validation: {
    range: string;
    h0: number;
    rmse_ft: number;
    bias_ft: number;
    max_abs_err_ft: number;
    [key: string]: unknown;
  };
}

/** A named inflow source (USGS gauge) with a display label. */
export interface RiverSource {
  key: string;
  label: string;
  /** Shown under the slider; e.g. "USGS 09331000". */
  note?: string;
}

/** The four committed data files for one lake. */
export interface LakeData {
  levels: LevelsData;
  inflows: InflowsData;
  elevArea: ElevAreaPoint[];
  calibration: CalibrationData;
}

/**
 * One year of total source inflow for the main chart, with a data-quality flag.
 * `estimated` is true when the year's total is not a full, complete measurement
 * (a source gauge is missing for the year, or the year is partial); those years
 * are drawn dotted so the reader can see where the inflow is an estimate.
 */
export interface InflowPoint {
  year: number;
  /** Total annual inflow in million acre-ft (MAF). */
  maf: number;
  /** True when the year's total is an estimate (see above) — drawn dotted. */
  estimated: boolean;
}

/** A point marked on the chart (e.g. a record low). */
export interface ChartMarker {
  /** Fractional year for x placement (e.g. 2022.85). */
  year: number;
  ft: number;
  label: string;
}

/** Everything a water dashboard needs for one lake. */
export interface LakeConfig {
  kind: "lake";
  slug: string;
  name: string;
  shortName: string;
  location: string;
  /** One-line description for the /water index card. */
  description: string;
  rivers: RiverSource[];
  /** [first, last] water years with inflow gauge data. */
  yearRange: [number, number];
  /** "Magic level" (historic average, ft) drawn on the chart, if any. */
  magicLevel?: number;
  /** Projection horizons offered by the dashboard (years). Default 5/10/15/20. */
  horizonOptions?: number[];
  /** Record-low marker drawn on the chart, if any. */
  lowMarker?: ChartMarker;
  data: LakeData;
}

// ---------------------------------------------------------------------------
// River (conduit) water bodies — the Bear River, which flows INTO a lake.
//
// A river is modeled as a flow budget, not a level: the response variable is
// the flow that reaches the receiving lake (acre-ft / water year), and the
// what-if sliders sit on the inflow components (in) and the diversions (out).
// The budget is  flow_to_lake = inflow − diversions − residual  where the
// residual covers river ET, seepage, storage change, and the gauge→mouth gap.

/** A named diversion (the "Out" side of the budget) with a display label. */
export interface DiversionSource {
  key: string;
  name: string;
  short?: string;
  /** Average annual diversion in acre-ft — the slider's 100% value. */
  avg_af: number;
  kind?: string;
  source?: string;
  /** Whether this diversion gets a what-if slider. */
  slider: boolean;
}

/** A named inflow component (the "In" side, decomposed from the source total). */
export interface InflowComponent {
  key: string;
  label: string;
  note?: string;
}

/** A named what-if scenario (e.g. a proposed new diversion). */
export interface RiverScenario {
  name: string;
  /** Additional diversion added by the scenario (acre-ft/yr). */
  new_diversion_af: number;
  /** Portion of the new diversion fully depleted (acre-ft/yr). */
  depleted_af: number;
  /** Implied lake-level drop (inches), if known. */
  lake_level_drop_inch?: number;
  source?: string;
}

/** One water year of measured river inflow (source-gauge total + split). */
export interface RiverInflowRow {
  year: number;
  /** Measured total inflow at the source gauge (acre-ft). */
  total: number | null;
  /** Mainstem share of the total (acre-ft). */
  mainstem: number | null;
  /** Tributary share of the total (acre-ft). */
  tributaries: number | null;
  /** Measured flow below the last diversion reach (acre-ft), if gauged. */
  below_oline: number | null;
  /** True when the source-gauge record is a full year. */
  complete: boolean;
}

/** The diversion + model-config block (shape of diversions.json). */
export interface RiverDiversionConfig {
  note?: string;
  units?: string;
  /** Diversions scale with available flow up to this fraction of inflow. */
  dry_take_cap: number;
  /** Residual losses as a fraction of inflow. */
  residual_frac: number;
  diversions: DiversionSource[];
  scenarios: Record<string, RiverScenario>;
  provenance?: string[];
}

/** The committed data files for one river. */
export interface RiverData {
  inflows: RiverInflowRow[];
  diversions: RiverDiversionConfig;
}

/** Everything a water dashboard needs for one river. */
export interface RiverConfig {
  kind: "river";
  slug: string;
  name: string;
  shortName: string;
  location: string;
  /** One-line description for the /water index card. */
  description: string;
  /** The source gauge that provides the measured inflow. */
  source: RiverSource;
  /** The inflow components (the "In" what-if sliders). */
  inflowComponents: InflowComponent[];
  /** [first, last] water years with source-gauge data. */
  yearRange: [number, number];
  data: RiverData;
}

/** Any registered water body (lake or river). */
export type WaterConfig = LakeConfig | RiverConfig;
